window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-a6474428dbe3ecc0"]={"versions": [{"id": "FIG-a6474428dbe3ecc0", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation eines Teilberechnungsschritts innerhalb des E2E Profile 4m der AUTOSAR Adaptive und Classic Platform (PRS E2E Protocol). Das Diagramm stellt den internen Teilschritt „Compute offset“ dar, der gleichermaßen für die Funktionen <code>E2E_P04mProtect()</code>, <code>E2E_P04mCheck()</code> und <code>E2E_P04mForward()</code> definiert ist (symbolisiert durch die referenzierten Funktionsblöcke am linken Rand).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Eingangskonfiguration / Schnittstelle</strong>: <code>Config-&gt;Offset</code> (Bit-Offset aus der Konfigurationsstruktur).\n</li><li><strong>Lokale Variable</strong>: <code>Offset</code> vom Datentyp <code>uint16</code> (Darstellung in Byte).\n</li><li><strong>Funktionskontexte</strong>: <code>E2E_P04mProtect()</code>, <code>E2E_P04mCheck()</code>, <code>E2E_P04mForward()</code>.\n</li><li><strong>Aktivitätsknoten</strong>: Initialknoten (Start), Aktionszustand <code>Offset = Config-&gt;Offset / 8</code>, Aktivitätsendknoten (Stop) sowie ein assoziierter Kommentar-Callout (<code>compute local variable uint16 Offset, which is in [byte]</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Die Aktivität startet am Initialknoten beim Eintritt in den Teilschritt „Compute offset“.\n</li><li>Ausführung der Aktion <code>Offset = Config-&gt;Offset / 8</code>: Der in Bits konfigurierte Offset (<code>Config-&gt;Offset</code>) wird durch 8 geteilt und der lokalen Variable <code>Offset</code> zugewiesen, um den Byte-Offset zu ermitteln.\n</li><li>Die Aktivität terminiert unmittelbar im Endknoten; die berechnete Variable steht den nachfolgenden Schritten der Schutz-, Prüf- bzw. Weiterleitungsfunktion zur Verfügung.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Berechnungsvorschrift gemäß AUTOSAR PRS E2E Protocol (Anforderung [PRS_E2E_00758]). Entwickler müssen sicherstellen, dass <code>Config-&gt;Offset</code> durch 8 teilbar ist bzw. die Division nach C-Ganzzahlarithmetik erfolgt und der resultierende Byte-Offset als <code>uint16</code> geführt wird. Dieser Teilschritt ist in allen drei Profil-4m-Funktionen (<code>Protect</code>, <code>Check</code>, <code>Forward</code>) identisch zu implementieren.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-b9e2ddfc0c9a4fd3", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation eines Teilberechnungsschritts innerhalb des E2E Profile 4m der AUTOSAR Adaptive und Classic Platform (PRS E2E Protocol). Das Diagramm stellt den internen Teilschritt „Compute offset“ dar, der gleichermaßen für die Funktionen <code>E2E_P04mProtect()</code>, <code>E2E_P04mCheck()</code> und <code>E2E_P04mForward()</code> definiert ist (symbolisiert durch die referenzierten Funktionsblöcke am linken Rand).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Eingangskonfiguration / Schnittstelle</strong>: <code>Config-&gt;Offset</code> (Bit-Offset aus der Konfigurationsstruktur).\n</li><li><strong>Lokale Variable</strong>: <code>Offset</code> vom Datentyp <code>uint16</code> (Darstellung in Byte).\n</li><li><strong>Funktionskontexte</strong>: <code>E2E_P04mProtect()</code>, <code>E2E_P04mCheck()</code>, <code>E2E_P04mForward()</code>.\n</li><li><strong>Aktivitätsknoten</strong>: Initialknoten (Start), Aktionszustand <code>Offset = Config-&gt;Offset / 8</code>, Aktivitätsendknoten (Stop) sowie ein assoziierter Kommentar-Callout (<code>compute local variable uint16 Offset, which is in [byte]</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Die Aktivität startet am Initialknoten beim Eintritt in den Teilschritt „Compute offset“.\n</li><li>Ausführung der Aktion <code>Offset = Config-&gt;Offset / 8</code>: Der in Bits konfigurierte Offset (<code>Config-&gt;Offset</code>) wird durch 8 geteilt und der lokalen Variable <code>Offset</code> zugewiesen, um den Byte-Offset zu ermitteln.\n</li><li>Die Aktivität terminiert unmittelbar im Endknoten; die berechnete Variable steht den nachfolgenden Schritten der Schutz-, Prüf- bzw. Weiterleitungsfunktion zur Verfügung.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Berechnungsvorschrift gemäß AUTOSAR PRS E2E Protocol (Anforderung [PRS_E2E_00758]). Entwickler müssen sicherstellen, dass <code>Config-&gt;Offset</code> durch 8 teilbar ist bzw. die Division nach C-Ganzzahlarithmetik erfolgt und der resultierende Byte-Offset als <code>uint16</code> geführt wird. Dieser Teilschritt ist in allen drei Profil-4m-Funktionen (<code>Protect</code>, <code>Check</code>, <code>Forward</code>) identisch zu implementieren.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-a6474428dbe3ecc0", "to": "FIG-b9e2ddfc0c9a4fd3", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
